INSERT INTO "ShopItem"(id,definition) VALUES ('streak-shield','{"id":"streak-shield","name":"Escudo da Ofensiva","price":140,"rarity":"rare","category":"ofensiva","kind":"consumable","max":3,"description":"Ative antes de precisar: protege um dia perdido, sem somar estudo ou recompensas. Não cobre dias consecutivos."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('question-pass','{"id":"question-pass","name":"Passe de Questão","price":100,"rarity":"rare","category":"consumiveis","kind":"consumable","max":20,"description":"Pula uma questão compatível. Vale zero acerto, encerra a sequência e impede lição perfeita. Exige confirmação."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('hint-scroll','{"id":"hint-scroll","name":"Pergaminho da Dica","price":35,"rarity":"common","category":"auxilio","kind":"consumable","max":20,"description":"Revela uma orientação contextual cadastrada, sem entregar a resposta. Só consome quando há dica válida."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('answer-lens','{"id":"answer-lens","name":"Lente das Alternativas","price":65,"rarity":"uncommon","category":"auxilio","kind":"consumable","max":20,"description":"Retira até duas opções incorretas, mantendo ao menos duas. Não funciona em perguntas com duas alternativas."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('example-scroll','{"id":"example-scroll","name":"Pergaminho do Exemplo","price":50,"rarity":"uncommon","category":"auxilio","kind":"consumable","max":20,"description":"Abre um exemplo adicional validado sobre a habilidade. O conteúdo básico continua gratuito."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('challenge-swap','{"id":"challenge-swap","name":"Troca de Desafio","price":110,"rarity":"rare","category":"auxilio","kind":"consumable","max":20,"description":"Troca a questão por uma variante da mesma habilidade e dificuldade. Não cria tentativas extras."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('tactical-delay','{"id":"tactical-delay","name":"Adiamento Tático","price":45,"rarity":"common","category":"consumiveis","kind":"consumable","max":20,"description":"Deixa a questão para o fim da primeira rodada, antes da revisão. Uma vez por questão; responder continua obrigatório."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('arcane-frame','{"id":"arcane-frame","name":"Moldura Arcana","price":160,"rarity":"epic","category":"cosmeticos","kind":"permanent","max":1,"description":"Desbloqueia uma moldura luminosa para o avatar. Você pode equipar ou retirar quando quiser."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('stellar-path','{"id":"stellar-path","name":"Caminho Estelar","price":220,"rarity":"epic","category":"cosmeticos","kind":"permanent","max":1,"description":"Um acabamento estelar para o mapa. Muda a aparência e preserva todos os bloqueios e progressos."}'::jsonb);
INSERT INTO "ShopItem"(id,definition) VALUES ('bito-companion','{"id":"bito-companion","name":"Companheiro do Bito","price":300,"rarity":"legendary","category":"especiais","kind":"permanent","max":1,"description":"Um pequeno robô acompanha áreas de exploração. Fica fora das lições e pode ser desativado na Mochila."}'::jsonb);
