ALTER TABLE "LearningPointProgress" ADD COLUMN "skippedEntries" TEXT[] NOT NULL DEFAULT '{}', ADD COLUMN "deferredEntries" TEXT[] NOT NULL DEFAULT '{}';
CREATE TABLE "RpgWallet" ("userId" TEXT PRIMARY KEY REFERENCES "User"(id) ON DELETE CASCADE,bits INTEGER NOT NULL DEFAULT 0 CHECK(bits>=0),"achievementXp" INTEGER NOT NULL DEFAULT 0 CHECK("achievementXp">=0),stats JSONB NOT NULL DEFAULT '{}',initialized BOOLEAN NOT NULL DEFAULT false);
CREATE TABLE "AchievementDefinition" (id TEXT PRIMARY KEY,definition JSONB NOT NULL);
CREATE TABLE "UserAchievement" ("userId" TEXT REFERENCES "User"(id) ON DELETE CASCADE,"achievementId" TEXT REFERENCES "AchievementDefinition"(id),"unlockedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),xp INTEGER NOT NULL,bits INTEGER NOT NULL,PRIMARY KEY("userId","achievementId"));
CREATE TABLE "AchievementProgress" ("userId" TEXT REFERENCES "User"(id) ON DELETE CASCADE,"achievementId" TEXT REFERENCES "AchievementDefinition"(id),current INTEGER NOT NULL DEFAULT 0 CHECK(current>=0),PRIMARY KEY("userId","achievementId"));
CREATE TABLE "RpgEvent" (id SERIAL PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,key TEXT NOT NULL,type TEXT NOT NULL,payload JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),UNIQUE("userId",key));
CREATE TABLE "CurrencyTransaction" (id SERIAL PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,key TEXT NOT NULL,kind TEXT NOT NULL,subject TEXT NOT NULL,bits INTEGER NOT NULL,xp INTEGER NOT NULL,"balanceAfter" INTEGER NOT NULL CHECK("balanceAfter">=0),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),UNIQUE("userId",key));
CREATE TABLE "ShopItem" (id TEXT PRIMARY KEY,definition JSONB NOT NULL);
CREATE TABLE "InventoryItem" ("userId" TEXT REFERENCES "User"(id) ON DELETE CASCADE,"itemId" TEXT REFERENCES "ShopItem"(id),quantity INTEGER NOT NULL DEFAULT 0 CHECK(quantity>=0),equipped BOOLEAN NOT NULL DEFAULT false,PRIMARY KEY("userId","itemId"));
CREATE TABLE "ItemUsage" (id SERIAL PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,"requestId" TEXT NOT NULL,"itemId" TEXT NOT NULL,"pointId" INTEGER,"entryKey" TEXT,action TEXT NOT NULL,result JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),UNIQUE("userId","requestId"));
CREATE TABLE "RpgQuestionState" ("userId" TEXT REFERENCES "User"(id) ON DELETE CASCADE,"pointId" INTEGER NOT NULL REFERENCES "TrailPoint"(id) ON DELETE CASCADE,"entryKey" TEXT NOT NULL,effects JSONB NOT NULL DEFAULT '{}',assisted BOOLEAN NOT NULL DEFAULT false,PRIMARY KEY("userId","pointId","entryKey"));
CREATE TABLE "StudyDay" ("userId" TEXT REFERENCES "User"(id) ON DELETE CASCADE,day TEXT NOT NULL,PRIMARY KEY("userId",day));
CREATE TABLE "UserStreakProtection" (id SERIAL PRIMARY KEY,"userId" TEXT NOT NULL REFERENCES "User"(id) ON DELETE CASCADE,"activatedDay" TEXT NOT NULL,"protectedDay" TEXT,state TEXT NOT NULL DEFAULT 'armed' CHECK(state IN ('armed','used','expired')),"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now());
CREATE UNIQUE INDEX "one_armed_protection" ON "UserStreakProtection"("userId") WHERE state='armed';
CREATE UNIQUE INDEX "one_protection_per_day" ON "UserStreakProtection"("userId","protectedDay") WHERE "protectedDay" IS NOT NULL;
CREATE INDEX "UserStreakProtection_userId_state_idx" ON "UserStreakProtection"("userId",state);
CREATE TABLE "MaterialReading" ("userId" TEXT REFERENCES "User"(id) ON DELETE CASCADE,"pointId" INTEGER NOT NULL REFERENCES "TrailPoint"(id) ON DELETE CASCADE,"entryKey" TEXT NOT NULL,"startedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT now(),"completedAt" TIMESTAMPTZ(3),PRIMARY KEY("userId","pointId","entryKey"));
